import { availabilityLabel, levelLabel, orgTree, personaById, type OrgNode } from "@/lib/org";
import type { Scenario } from "@/lib/types";
import { YOU } from "@/lib/types";
import Avatar from "./Avatar";

interface Props {
  scenario: Scenario;
  youName: string;
  onOpenDm: (personaId: string) => void;
}

// The reporting hierarchy, generated by Gemini and arranged by code.
export default function OrgChart({ scenario, youName, onOpenDm }: Props) {
  const roots = orgTree(scenario);
  const externals = scenario.personas.filter((p) => p.isExternal);

  return (
    <div className="space-y-5">
      <div>
        <h3 className="mb-2 text-xs font-semibold uppercase tracking-wide text-slate-500">
          {scenario.company.name}
        </h3>
        <ul className="space-y-1">
          {roots.map((n) => (
            <Node key={n.id} node={n} depth={0} {...{ scenario, youName, onOpenDm }} />
          ))}
        </ul>
      </div>
      {externals.length > 0 && (
        <div>
          <h3 className="mb-2 text-xs font-semibold uppercase tracking-wide text-slate-500">Outside the company</h3>
          <ul className="space-y-1">
            {externals.map((p) => (
              <Node key={p.id} node={{ id: p.id, children: [] }} depth={0} {...{ scenario, youName, onOpenDm }} />
            ))}
          </ul>
        </div>
      )}
      <p className="text-xs leading-relaxed text-slate-500">
        Tip: messaging someone above your manager directly is noticed. Click a person to message them.
      </p>
    </div>
  );
}

function Node({ node, depth, scenario, youName, onOpenDm }: Props & { node: OrgNode; depth: number }) {
  const isYou = node.id === YOU;
  const p = personaById(scenario, node.id);

  const body = (
    <div
      className={`flex items-center gap-2.5 rounded-lg border px-2.5 py-2 text-left ${
        isYou ? "border-teal-300 bg-teal-50" : "border-slate-200 bg-white hover:border-slate-300 hover:bg-slate-50"
      }`}
    >
      <Avatar scenario={scenario} id={node.id} youName={youName} size={30} status />
      <div className="min-w-0 flex-1">
        <div className="flex items-center gap-1.5">
          <span className="truncate text-sm font-medium text-slate-900">{isYou ? `${youName} (you)` : p?.name}</span>
        </div>
        <div className="truncate text-xs text-slate-500">{isYou ? scenario.graduateTitle : p?.title}</div>
      </div>
      {p && (
        <div className="flex shrink-0 flex-col items-end gap-0.5">
          <span className="rounded bg-slate-100 px-1.5 py-0.5 text-[10px] font-medium text-slate-600">{levelLabel(p)}</span>
          <span className="text-[10px] text-slate-400">{availabilityLabel(p)}</span>
        </div>
      )}
    </div>
  );

  return (
    <li>
      <div style={{ marginLeft: depth * 16 }} className={depth > 0 ? "relative before:absolute before:-left-2.5 before:top-0 before:h-1/2 before:w-2 before:border-b before:border-l before:border-slate-300 before:rounded-bl" : ""}>
        {isYou ? body : (
          <button type="button" className="block w-full" onClick={() => onOpenDm(node.id)}>
            {body}
          </button>
        )}
      </div>
      {node.children.length > 0 && (
        <ul className="mt-1 space-y-1">
          {node.children.map((c) => (
            <Node key={c.id} node={c} depth={depth + 1} {...{ scenario, youName, onOpenDm }} />
          ))}
        </ul>
      )}
    </li>
  );
}
